 ".github/workflows/publish.yml": "# Publish the skill on PyPI when you make a release on GitHub.\n#\n# Once, on pypi.org: Your account → Publishing → \"Add a new pending publisher\"\n# with this repository's owner and name, workflow \"publish.yml\" and\n# environment \"pypi\". No password or token is stored anywhere: GitHub proves\n# to PyPI that this workflow runs in your repository (Trusted Publishing).\n#\n# Then each new version: Releases → \"Draft a new release\" → a tag like v0.1.1\n# → Publish. The version on PyPI is the tag without its \"v\".\nname: Publish to PyPI\non:\n  release:\n    types: [published]\npermissions:\n  contents: read\n  id-token: write\njobs:\n  pypi:\n    # not the templates themselves (emkay-voice/ovos-skill-*-example) – written\n    # so that \"Make it yours\" and Emkay: New skill, which put your repository's\n    # name in place of the template's, leave this line alone\n    if: ${{ github.repository_owner != 'emkay-voice' || !endsWith(github.event.repository.name, '-example') }}\n    runs-on: ubuntu-latest\n    environment: pypi\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-python@v5\n        with: { python-version: \"3.12\" }\n      - name: The release's version\n        run: sed -i \"s/^version = .*/version = \\\"${GITHUB_REF_NAME#v}\\\"/\" pyproject.toml\n      - run: pip install build && python -m build\n      - uses: pypa/gh-action-pypi-publish@release/v1\n",
