 "pyproject.toml": "[build-system]\nrequires = [\"setuptools>=64\"]\nbuild-backend = \"setuptools.build_meta\"\n\n[project]\nname = \"{{name}}\"\nversion = \"0.1.0\"\ndescription = \"My first OpenVoiceOS skill: say \\\"hello from my skill\\\" and it answers\"\nreadme = \"README.md\"\nlicense = {text = \"Apache-2.0\"}\nauthors = [{name = \"{{author}}\"}]\nrequires-python = \">=3.10\"\nkeywords = [\"ovos\", \"openvoiceos\", \"skill\", \"emkay\"]\nclassifiers = [\n    \"Development Status :: 3 - Alpha\",\n    \"License :: OSI Approved :: Apache Software License\",\n    \"Programming Language :: Python :: 3\",\n]\n# what the skill needs besides OpenVoiceOS itself; Emkay installs these too\ndependencies = [\n    \"ovos-workshop>=0.0.15,<10.0.0\",\n]\n\n[project.optional-dependencies]\ntest = [\"pytest\", \"ovos-bus-client\"]\n\n[project.urls]\nHomepage = \"https://github.com/{{repo}}\"\n\n# how OpenVoiceOS finds the skill: \"<skill id>\" = \"<package>:<class>\"\n[project.entry-points.\"opm.skill\"]\n\"{{id}}\" = \"{{module}}:{{Class}}\"\n\n[tool.setuptools]\npackages = [\"{{module}}\"]\n\n[tool.setuptools.package-data]\n{{module}} = [\"locale/**/*\"]\n\n[tool.pytest.ini_options]\naddopts = \"--import-mode=importlib\"\ntestpaths = [\"tests\"]\n",
